<template>
  <div class="flex flex-col gap-4">
    <PageTitle size="sm" title="Payroll" />
    <AppLoader v-if="isLoading" subject="dashboard" />
    <AppError v-else-if="error" title="Failed to load dashboard" :error="error" />
    <AppEmpty v-else-if="!payroll?.projects.length" subject="payroll" />
    <AccordionTable v-else label-name="Projects" :groups="groups" :rows="rows" />
  </div>
</template>

<script setup lang="ts">
import type { PayrollDashboard, TotalPayrollRecord } from '~/client';
import {
  accordionCellKey,
  type AccordionCellContent,
  type AccordionGroup,
  type AccordionRow,
  type AccordionTone,
  type AccordionVariant,
  type AccordionColumn,
} from '~/components/common/accordion-table/AccordionTable.vue';

definePageMeta({
  backGroup: 'system-dashboard',
  roles: ['admin'],
  backLabel: 'dashboard',
});

const { data, error, isLoading, params, defaultDate } = useSystemDashboard<PayrollDashboard>(
  'Payroll',
  'system-dashboard-payroll'
);

const payroll = computed(() => data.value ?? null);

const usd = (value: number | null | undefined): AccordionCellContent => ({ type: 'currency', value: value ?? null });

const PERIOD_NAMES = ['Last', 'This', 'Next'];
const periodLabels = computed(() =>
  (payroll.value?.total.payrolls ?? []).map((p, i) => ({
    label: `${PERIOD_NAMES[i] ?? `P${i + 1}`} · ${formatDateToFormat(p.timestamp, 'M/d/yyyy')}`,
    shortLabel: formatDateToFormat(p.timestamp, 'M/d/yyyy'),
  }))
);

const groups = computed<AccordionGroup[]>(() => [
  {
    columns: [{ label: 'Total Spend' }],
    breakdowns: [
      { label: 'Received', tone: 'default' },
      { label: 'Contract', tone: 'default' },
    ],
  },
  {
    columns: periodLabels.value,
    breakdowns: [
      { label: 'Same Day', tone: 'default' },
      { label: 'Pending', tone: 'warning' },
      { label: 'Rejected', tone: 'destructive' },
      { label: 'System', tone: 'default' },
      { label: 'Manual', tone: 'default' },
    ],
  },
]);

const rowTone = (record: TotalPayrollRecord): AccordionTone => {
  const { total_spend, received, contract } = record.total_spend;
  if (contract != null && total_spend > contract) return 'destructive';
  if (received != null && total_spend > received) return 'warning';
  return 'default';
};

const toRow = (record: TotalPayrollRecord, id: string, isTotal: boolean): AccordionRow => {
  const tone = rowTone(record);
  const variant: AccordionVariant = isTotal ? 'total' : 'default';
  const cells: AccordionRow['data'] = {
    [accordionCellKey('Total Spend')]: { value: usd(record.total_spend.total_spend), tone },
    [accordionCellKey('Total Spend', 'Received')]: { value: usd(record.total_spend.received) },
    [accordionCellKey('Total Spend', 'Contract')]: { value: usd(record.total_spend.contract) },
  };

  record.payrolls.forEach((p, i) => {
    const column = periodLabels.value[i].label;
    cells[accordionCellKey(column)] = { value: usd(p.total_spend) };
    cells[accordionCellKey(column, 'Same Day')] = { value: usd(p.same_day) };
    cells[accordionCellKey(column, 'Pending')] = { value: usd(p.pending || null) };
    cells[accordionCellKey(column, 'Rejected')] = { value: usd(p.rejected) };
    cells[accordionCellKey(column, 'System')] = { value: usd(p.system) };
    cells[accordionCellKey(column, 'Manual')] = { value: usd(p.manual) };
  });

  return { id, label: record.name, variant, tone, data: cells };
};

const rows = computed<AccordionRow[]>(() => {
  if (!payroll.value) return [];
  return [
    toRow(payroll.value.total, 'total', true),
    ...payroll.value.projects.map((record) => toRow(record, record.id, false)),
  ];
});
</script>
