const fullFormatter = new Intl.NumberFormat('en-US', {
  style: 'currency',
  currency: 'USD',
  maximumFractionDigits: 0,
});

const compactFormatter = new Intl.NumberFormat('en-US', {
  style: 'currency',
  currency: 'USD',
  notation: 'compact',
  maximumSignificantDigits: 3,
});

export const formatUsd = (value: number) => fullFormatter.format(value);

export const formatUsdCompact = (value: number) => compactFormatter.format(value);
