<template>
  <div class="md:max-h-[80vh] md:overflow-auto md:rounded-lg md:border md:bg-background">
    <!-- TABLE WRAPER -->
    <div
      data-testid="accordion-table"
      class="grid gap-3 md:gap-0 text-sm md:[grid-template-columns:var(--accordion-cols)] md:[min-width:var(--accordion-min-width)]"
      :style="{ '--accordion-cols': gridTemplateColumns, '--accordion-min-width': tableMinWidth + 'px' }"
    >
      <!-- TABLE HEADER -->
      <div class="hidden md:contents text-xs leading-6 font-semibold text-accent-foreground sm:text-sm">
        <div class="sticky left-0 top-0 z-40 border-b border-r bg-accent px-3 py-2 text-left">
          {{ labelName }}
        </div>
        <template v-for="group in groupsUnpacked" :key="group.group">
          <!-- Spacer header over the breakdown-label column (no column name). -->
          <div class="sticky top-0 z-30 border-b bg-accent px-3 py-2" aria-hidden="true" />
          <div
            v-for="column in groupColumnUnpacked(group)"
            :key="column.column"
            class="sticky top-0 z-30 border-b bg-accent px-3 py-2 text-right whitespace-nowrap"
            :class="{ 'border-r': isLastInGroup(column) }"
          >
            {{ columnName(column).label }}
          </div>
        </template>
      </div>

      <!-- TABLE ROWS -->
      <div
        v-for="(row, ri) in rows"
        :key="row.id"
        class="grid grid-cols-1 gap-1 overflow-hidden md:contents pb-1 border rounded-md"
        :class="[...applyVariant(row.variant), { 'bg-background': row.variant === 'default' }]"
      >
        <!-- LABEL CELL -->
        <div
          class="min-w-0 md:sticky md:left-0 md:z-20 md:border-r border-b md:p-0 text-base font-medium md:font-normal"
          :class="{ 'bg-background': row.variant === 'default', 'bg-accent': row.variant === 'total' }"
        >
          <button
            type="button"
            class="flex w-full cursor-pointer items-start gap-2 px-2 md:px-3 py-2 md:py-2 text-left select-none"
            data-testid="accordion-table-row-toggle"
            :aria-expanded="expanded.has(row.id)"
            :aria-label="`${expanded.has(row.id) ? 'Collapse' : 'Expand'} ${row.label}`"
            @click="toggle(row.id)"
          >
            <ChevronRight
              class="size-4 shrink-0 text-muted-foreground transition-transform mt-1"
              :class="{ 'rotate-90': expanded.has(row.id) }"
            />
            <span
              class="block min-w-0"
              :class="[...applyTones(rowTone(ri)), { truncate: !expanded.has(row.id) }]"
              :title="row.label"
            >
              {{ row.label }}
            </span>
          </button>
        </div>

        <!-- GROUPS -->
        <div
          v-for="group in groupsUnpacked"
          :key="group.group"
          class="grid [grid-template-columns:var(--group-cols)] md:grid-cols-subgrid md:[grid-column:span_var(--group-span)] md:border-r border-b last:border-b-0 md:border-b md:last:border-b p-0 text-right"
          :style="{
            '--group-cols': `repeat(${groupColumns(group).length + 1}, minmax(0, 1fr))`,
            '--group-span': groupColumns(group).length + 1,
          }"
          :class="{ 'bg-background': row.variant === 'default', 'bg-accent': row.variant === 'total' }"
        >
          <!-- MOBILE HEADER -->
          <div class="contents md:hidden h-10 text-xs">
            <div class="px-3 py-1" aria-hidden="true" />
            <div v-for="column in groupColumnUnpacked(group)" :key="column.column" class="px-3 py-1">
              {{ columnName(column).shortLabel ?? columnName(column).label }}
            </div>
          </div>

          <!-- HEAD ROWS -->
          <div class="group/bd contents text-base font-bold">
            <div
              class="flex items-center h-10 px-3 group-hover/bd:bg-muted/50 text-muted-foreground text-sm font-medium"
              aria-hidden="true"
            >
              <span class="md:hidden">Total</span>
            </div>
            <div
              v-for="column in groupColumnUnpacked(group)"
              :key="column.column"
              class="flex items-center justify-end h-10 whitespace-nowrap px-3 group-hover/bd:bg-muted/50"
              :class="applyTones(cellTone({ ...column, row: ri }))"
            >
              <AccordionTableCellValue :content="cellContent({ ...column, row: ri })" />
            </div>
          </div>

          <!-- BREAKDOWNS -->
          <div
            class="col-span-full grid grid-cols-subgrid transition-[grid-template-rows] duration-75 ease-out motion-reduce:transition-none"
            :class="expanded.has(row.id) ? '[grid-template-rows:1fr]' : '[grid-template-rows:0fr]'"
            :aria-hidden="!expanded.has(row.id)"
          >
            <div class="col-span-full grid grid-cols-subgrid overflow-hidden min-h-0">
              <div
                v-for="(breakdown, bri) in groupBreakdowns(group)"
                :key="breakdown.label"
                class="group/bd contents text-sm font-medium"
              >
                <div
                  class="flex items-center h-8 px-3 text-left whitespace-nowrap group-hover/bd:bg-muted/50"
                  :class="[
                    breakdown.tone === 'default' ? 'text-muted-foreground' : applyTones(breakdown.tone),
                    { 'md:border-b': bri !== groupBreakdowns(group).length - 1 },
                  ]"
                >
                  {{ breakdown.label }}
                </div>
                <div
                  v-for="column in groupColumnUnpacked(group)"
                  :key="column.column"
                  class="flex items-center justify-end h-8 px-3 group-hover/bd:bg-muted/50"
                  :class="{ 'md:border-b': bri !== groupBreakdowns(group).length - 1 }"
                >
                  <span
                    class="md:font-semibold tabular-nums whitespace-nowrap"
                    :class="applyTones(breakdown.tone, cellTone({ ...column, row: ri, breakdown: bri }))"
                  >
                    <AccordionTableCellValue :content="cellContent({ ...column, row: ri, breakdown: bri })" />
                  </span>
                </div>
              </div>
              <div
                v-for="i in Array(longestBreakdown - groupBreakdowns(group).length).keys()"
                :key="i"
                class="hidden md:block h-8 col-span-full"
              />
            </div>
          </div>
        </div>
      </div>
    </div>
  </div>
</template>

<script lang="ts">
export type AccordionVariant = 'default' | 'total';
export type AccordionTone = 'default' | 'warning' | 'destructive';

export type AccordionCellContent = { type: 'currency'; value: number | null } | { type: 'text'; value: string };

export interface AccordionCell {
  value: AccordionCellContent;
  // Optional headline-cell tone (e.g. a status colour). Breakdown cells take their tone from
  // the group's breakdown definition instead.
  tone?: AccordionTone;
}

export interface AccordionBreakdown {
  label: string;
  tone: AccordionTone;
}

export interface AccordionColumn {
  label: string;
  shortLabel?: string;
}

export interface AccordionGroup {
  // Headline column labels, e.g. ['Total Spend'] or ['Last · 1/2', 'This · 1/9', 'Next · 1/16'].
  columns: AccordionColumn[];
  // Breakdown sub-rows revealed on expand, e.g. [{ label: 'Pending', tone: 'warning' }, …].
  breakdowns: AccordionBreakdown[];
}

export interface AccordionRow {
  // Stable, unique row identity (e.g. an entity id). Used as the Vue key and surfaced for
  // navigation. Synthetic rows (e.g. a totals row) supply their own sentinel id.
  id: string;
  // Row label (e.g. an entity name / a totals label).
  label: string;
  variant?: AccordionVariant;
  tone?: AccordionTone;
  // Headline cells keyed by column label; breakdown cells keyed via accordionCellKey().
  data: Record<string, AccordionCell>;
}

// Builds the key for a cell in AccordionRow.data. Pass only the column for a headline cell,
// or the column + breakdown label for a breakdown cell. The page and the component must agree
// on this so keys never drift.
export function accordionCellKey(column: string, breakdown?: string) {
  return breakdown ? `${column} · ${breakdown}` : column;
}
</script>

<script setup lang="ts">
import { ChevronRight } from 'lucide-vue-next';

interface Props {
  // First column header, e.g. 'Projects'.
  labelName: string;
  groups: AccordionGroup[];
  rows: AccordionRow[];
}

const props = defineProps<Props>();

// Fixed column widths give the table a minimum width so it scrolls horizontally inside its
// container instead of squeezing columns when there isn't enough space.
const LABEL_WIDTH = 280;
const COLUMN_WIDTH = 150;

interface Group {
  group: number;
}

interface Column extends Group {
  column: number;
}

interface Cell extends Column {
  row: number;
}

interface BreakdownCell extends Cell {
  breakdown: number;
}

const groupsUnpacked = computed(() => props.groups.map((_, gi) => ({ group: gi })));
const columnsUnpacked = computed(() =>
  props.groups.flatMap((group, gi) => group.columns.map((_, ci) => ({ group: gi, column: ci })))
);
// The breakdown-label column is sized from its longest label (content-derived) but applied as a
// fixed px width so the outer header table and the per-row inner tables line up exactly.
const BREAKDOWN_LABEL_CHAR_PX = 8;
const BREAKDOWN_LABEL_PADDING_PX = 28;
const groupLabelWidth = (gi: number) =>
  Math.ceil(
    props.groups[gi].breakdowns.reduce((max, b) => Math.max(max, b.label.length), 0) * BREAKDOWN_LABEL_CHAR_PX +
      BREAKDOWN_LABEL_PADDING_PX
  );
const tableMinWidth = computed(
  () =>
    LABEL_WIDTH +
    columnsUnpacked.value.length * COLUMN_WIDTH +
    props.groups.reduce((sum, _g, gi) => sum + groupLabelWidth(gi), 0)
);
const gridTemplateColumns = computed(() => {
  const tracks = [`minmax(0, ${LABEL_WIDTH}fr)`];
  props.groups.forEach((group, gi) => {
    tracks.push(`minmax(0, ${groupLabelWidth(gi)}fr)`);
    group.columns.forEach(() => tracks.push(`minmax(0, ${COLUMN_WIDTH}fr)`));
  });
  return tracks.join(' ');
});
const longestBreakdown = computed(() => Math.max(...props.groups.map((g) => g.breakdowns.length)));
const groupBreakdowns = (data: Group) => props.groups[data.group].breakdowns;
const groupColumns = (data: Group) => props.groups[data.group].columns;
const groupColumnUnpacked = (data: Group) =>
  props.groups[data.group].columns.map((_, ci) => ({ group: data.group, column: ci }));

const isFirstInGroup = (data: Column) => data.column === 0;
const isLastInGroup = (data: Column) => props.groups[data.group].columns.length - 1 === data.column;

const rowTone = (row_i: number) => props.rows[row_i].tone;

const columnName = (data: Column) => props.groups[data.group].columns[data.column];
const breakdownName = (data: BreakdownCell) => props.groups[data.group].breakdowns[data.breakdown];

const getCell = (data: Cell | BreakdownCell): AccordionCell =>
  props.rows[data.row].data[
    accordionCellKey(columnName(data).label, 'breakdown' in data ? breakdownName(data).label : undefined)
  ] ?? { value: { type: 'text', value: '' } };
const cellContent = (data: Cell | BreakdownCell) => getCell(data).value;
const cellTone = (data: Cell | BreakdownCell) => getCell(data).tone;

const toneMap: Record<AccordionTone, string> = {
  default: 'text-foreground',
  warning: 'text-warning-foreground',
  destructive: 'text-destructive',
};
const applyTones = (...tones: (AccordionTone | undefined)[]) => tones.filter((t) => !!t).map((t) => toneMap[t]);

const variantMap: Record<AccordionVariant, string> = {
  default: '',
  total: 'bg-accent',
};
const applyVariant = (...variants: (AccordionVariant | undefined)[]) =>
  variants.filter((v) => !!v).map((v) => variantMap[v]);

const expanded = ref<Set<string>>(new Set());
const toggle = (i: string) => {
  const next = new Set(expanded.value);
  if (next.has(i)) next.delete(i);
  else next.add(i);
  expanded.value = next;
};
</script>
